#### 1. Update Living Specification (`openspec.md`)

```markdown
# Living System Specification

## User Management Service
- Handles user profiles, authentication tokens, and notification preferences.
- Endpoints: GET /api/v1/user, POST /api/v1/user/settings.

## Account Service (gRPC)
- Replaces legacy `AccountController`.
- Service definition: `AccountService` (`account_service.proto`).
- Methods:
  - `GetAccount(GetAccountRequest) returns (AccountResponse)`
  - `CreateAccount(CreateAccountRequest) returns (AccountResponse)`
  - `UpdateAccount(UpdateAccountRequest) returns (AccountResponse)`
- Field Semantics:
  - `status`: Optional enum `AccountStatus { UNSPECIFIED = 0; ACTIVE = 1; INACTIVE = 2; }` using protobuf field presence (`optional` or `google.protobuf.FieldMask`) to allow partial updates. Unset status indicates no change.
```

#### 2. gRPC Protobuf Definition (`account_service.proto`)

```protobuf
syntax = "proto3";

package account.v1;

enum AccountStatus {
  ACCOUNT_STATUS_UNSPECIFIED = 0;
  ACTIVE = 1;
  INACTIVE = 2;
}

message Account {
  string id = 1;
  string email = 2;
  AccountStatus status = 3;
  int64 updated_at = 4;
}

message GetAccountRequest {
  string id = 1;
}

message CreateAccountRequest {
  string email = 1;
  AccountStatus status = 2;
}

message UpdateAccountRequest {
  string id = 1;
  optional string email = 2;
  optional AccountStatus status = 3; // Optional presence distinguishes null/unset from ACTIVE/INACTIVE
}

message AccountResponse {
  Account account = 1;
}

service AccountService {
  rpc GetAccount(GetAccountRequest) returns (AccountResponse);
  rpc CreateAccount(CreateAccountRequest) returns (AccountResponse);
  rpc UpdateAccount(UpdateAccountRequest) returns (AccountResponse);
}
```

#### 3. gRPC Service Implementation (`account_service.py`)

```python
import grpc
import time
from typing import Dict, Optional
import account_service_pb2 as pb2
import account_service_pb2_grpc as pb2_grpc

# In-memory storage for demonstration / persistence layer integration
ACCOUNTS_DB: Dict[str, dict] = {}


class AccountServiceServicer(pb2_grpc.AccountServiceServicer):

    def GetAccount(self, request: pb2.GetAccountRequest, context: grpc.ServicerContext) -> pb2.AccountResponse:
        account_data = ACCOUNTS_DB.get(request.id)
        if not account_data:
            context.abort(grpc.StatusCode.NOT_FOUND, f"Account {request.id} not found")

        return pb2.AccountResponse(
            account=pb2.Account(
                id=account_data["id"],
                email=account_data["email"],
                status=account_data["status"],
                updated_at=account_data["updated_at"],
            )
        )

    def CreateAccount(self, request: pb2.CreateAccountRequest, context: grpc.ServicerContext) -> pb2.AccountResponse:
        account_id = f"acc_{int(time.time() * 1000)}"
        status = request.status if request.status != pb2.ACCOUNT_STATUS_UNSPECIFIED else pb2.ACTIVE

        account_data = {
            "id": account_id,
            "email": request.email,
            "status": status,
            "updated_at": int(time.time()),
        }
        ACCOUNTS_DB[account_id] = account_data

        return pb2.AccountResponse(
            account=pb2.Account(
                id=account_data["id"],
                email=account_data["email"],
                status=account_data["status"],
                updated_at=account_data["updated_at"],
            )
        )

    def UpdateAccount(self, request: pb2.UpdateAccountRequest, context: grpc.ServicerContext) -> pb2.AccountResponse:
        account_data = ACCOUNTS_DB.get(request.id)
        if not account_data:
            context.abort(grpc.StatusCode.NOT_FOUND, f"Account {request.id} not found")

        # Partial Patch Logic: Only update fields that are explicitly set
        if request.HasField("email"):
            account_data["email"] = request.email

        if request.HasField("status"):
            account_data["status"] = request.status

        account_data["updated_at"] = int(time.time())
        ACCOUNTS_DB[request.id] = account_data

        return pb2.AccountResponse(
            account=pb2.Account(
                id=account_data["id"],
                email=account_data["email"],
                status=account_data["status"],
                updated_at=account_data["updated_at"],
            )
        )
```

